"""Structured random request generator: realistic motifs, runs, matches."""
import json, random

ALPHA = [1400, 1450, 1500, 1515, 1520, 1560, 1600, 1650, 1700, 1750, 1800, 1900, 2000, 2400, 2900, 1000, 1200, 1300]

def motifs_for(rnd, classes, width, count):
    out = {}
    for c in range(classes):
        ms = []
        for _ in range(count):
            L = rnd.randint(2, width)
            ms.append(tuple(rnd.choice(ALPHA) for _ in range(L)))
        out[c] = ms
    return out

def gen_request(seed):
    rnd = random.Random(seed * 7919 + 13)
    capacity = {'range': rnd.choice([0, 1, 2, 3, 4, 8]), 'exact': rnd.choice([0, 1, 2, 3, 6])}
    nrel = rnd.randint(1, 3)
    releases = []
    plan = []
    for r in range(nrel):
        classes = rnd.randint(1, 3)
        width = rnd.randint(2, 5)
        mode = rnd.choice(['range', 'exact'])
        mot = motifs_for(rnd, classes, width, rnd.randint(1, 3))
        background = [rnd.choice(ALPHA) for _ in range(4)]
        disc = []
        for c in range(classes):
            if rnd.random() < 0.15:
                continue
            for _ in range(rnd.randint(1, 4)):
                values = []; act = []
                for _ in range(rnd.randint(1, 4)):
                    m = rnd.choice(mot[c])
                    for v in m:
                        values.append(v); act.append(1000)
                    for _ in range(rnd.randint(3, 5)):
                        values.append(rnd.choice(background)); act.append(0)
                disc.append({'class': c, 'values': values, 'activation': act})
        if not disc:
            c = 0
            m = mot[c][0]
            values = list(m) + [rnd.choice(background) for _ in range(4)]
            disc = [{'class': c, 'values': values, 'activation': [1000]*len(m) + [0]*4}]
        train = []
        for c in range(classes):
            for _ in range(rnd.randint(1, 2)):
                m = rnd.choice(mot[c])
                n = rnd.randint(0, width+1)
                values = list(m[:n]) if rnd.random() < 0.6 else [rnd.choice(ALPHA) for _ in range(n)]
                train.append({'class': c, 'values': values})
        valid = []
        for c in range(classes):
            for _ in range(rnd.randint(1, 4)):
                if rnd.random() < 0.7:
                    m = rnd.choice(mot[rnd.randrange(classes)])
                    pre = [rnd.choice(background) for _ in range(rnd.randint(0, 2))] + list(m)
                    tail = [rnd.choice(background) for _ in range(rnd.randint(0, 2))]
                    values = pre + tail
                else:
                    values = [rnd.choice(ALPHA) for _ in range(rnd.randint(0, 6))]
                valid.append({'class': c, 'values': values})
        releases.append({'id': 'rel%d' % r, 'classes': classes, 'width': width,
                         'eps': [rnd.choice([0, 1, 100, 600, 1000000]), rnd.choice([1, 1000])],
                         'ratio': [rnd.choice([0, 0, 1, 2]), rnd.choice([1, 2])],
                         'threshold': [rnd.choice([0, 1, 1, 3, 50]), rnd.choice([1, 4])],
                         'mode': mode,
                         'packet_limit': rnd.randint(width, 14),
                         'idle_us': rnd.choice([0, 0, 5, 50, 100000]),
                         'discovery': disc, 'train': train, 'validation': valid})
        plan.append({'mot': mot, 'width': width, 'classes': classes})
    ids = [r['id'] for r in releases]
    # operations
    ops = []
    active = {}
    epoch_count = {}
    direction = {}
    feats = {}
    stamps = {}
    current = None
    open_ok = lambda: current is not None
    for step in range(rnd.randint(3, 40)):
        roll = rnd.random()
        if roll < 0.18 or current is None:
            rid = rnd.choice(ids)
            ops.append(['install', rid]); current = rid
        elif roll < 0.32:
            cand = [f for f in ('a', 'b', 'c') if f not in active]
            if not cand or not open_ok(): continue
            f = rnd.choice(cand)
            active[f] = current; epoch_count[f] = epoch_count.get(f, 0)
            ops.append(['open', f])
            idx = ids.index(current)
            direction[f] = rnd.randint(0, 1); feats[f] = []; stamps[f] = None
        elif roll < 0.85:
            if not active: continue
            f = rnd.choice(list(active))
            idx = ids.index(active[f]); pl = plan[idx]
            if feats[f] and rnd.random() < 0.75:
                # continue or finish a motif
                tail = None
                for c in range(pl['classes']):
                    for m in pl['mot'][c]:
                        L = len(m)
                        if len(feats[f]) >= L and tuple(feats[f][-L:]) == tuple(m[:0]):
                            pass
                # choose a random motif to append fully
                c = rnd.randrange(pl['classes']); m = rnd.choice(pl['mot'][c])
                seq = list(m)
            else:
                seq = [rnd.choice(ALPHA) for _ in range(rnd.randint(1, 4))]
            for v in seq:
                if stamps[f] is not None and rnd.random() < 0.05:
                    ts = stamps[f]  # repeat (valid) or go back (invalid)
                    if rnd.random() < 0.3:
                        ts = max(0, stamps[f] - rnd.randint(1, 10))
                else:
                    ts = 0 if stamps[f] is None else stamps[f] + rnd.randint(0, 100)
                stamps[f] = ts
                if v > 1514:
                    length = v - 1514
                    src = direction[f]
                else:
                    length = 1514 - v
                    src = 1 - direction[f]
                ops.append(['packet', f, ts, src, length])
                feats[f] = feats[f] + [v]
        else:
            if not active: continue
            f = rnd.choice(list(active)); del active[f]
            ops.append(['close', f])
    for f in list(active):
        if rnd.random() < 0.85:
            del active[f]; ops.append(['close', f])
    blocks = []
    i = 0
    while i < len(ops):
        step = rnd.randint(1, 4)
        blocks.append(ops[i:i+step]); i += step
    return {'capacity': capacity, 'releases': releases, 'blocks': blocks}

if __name__ == '__main__':
    import sys
    print(json.dumps(gen_request(int(sys.argv[1]))))
